// app/admin/titles/page.tsx
import { Suspense } from 'react';
import { getCachedPeriods, getCachedTitles } from '@/lib/data/cache';
import { TitlesTable } from './TitlesTable';
import { CreateTitleForm } from './CreateTitleForm';
import { TableSkeleton } from '@/components/ui/skeleton';

interface PageProps {
  searchParams: {
    page?: string;
    search?: string;
    period?: string;
  };
}

export default async function TitlesPage({ searchParams }: PageProps) {
  const page = Number(searchParams.page) || 1;
  const search = searchParams.search || '';
  const periodId = searchParams.period ? Number(searchParams.period) : undefined;

  // Parallel fetching
  const [titlesData, periods] = await Promise.all([
    getCachedTitles({ page, search, periodId }),
    getCachedPeriods(),
  ]);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold">Titles Management</h1>
        <CreateTitleForm periods={periods} />
      </div>

      <Suspense fallback={<TableSkeleton rows={10} />}>
        <TitlesTable
          titles={titlesData.items}
          pagination={titlesData.pagination}
          periods={periods}
        />
      </Suspense>
    </div>
  );
}
